using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "RestorationBurstCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Hevelius/RestorationBurstCustomDescription", order = 0)]
public class RestorationBurstCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		BattleAction battleAction2 = (battleAction as RestorationBurstAction).BattleAction;
		string rawLocalizedDescription = GetRawLocalizedDescription(battleAction);
		string arg = battleAction2.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified)).RemoveLast();
		return Smart.Format(rawLocalizedDescription, arg);
	}
}
